import{_ as a,o as c,c as o,a5 as t}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Remove Agency (FR 3.4.6)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-6-remove-agency/plan.md","filePath":"feature/agency-workspace/3-4-6-remove-agency/plan.md"}'),d={name:"feature/agency-workspace/3-4-6-remove-agency/plan.md"};function n(s,e,r,i,l,h){return c(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="plan-—-remove-agency-fr-3-4-6" tabindex="-1">Plan — Remove Agency (FR 3.4.6) <a class="header-anchor" href="#plan-—-remove-agency-fr-3-4-6" aria-label="Permalink to &quot;Plan — Remove Agency (FR 3.4.6)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho Owner xóa mềm Agency (cascade Workspace con), khôi phục được trong 30 ngày.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>AgencyServiceImpl.removeAgency()</code> + <code>AgencyServiceImpl.restoreAgency()</code></td></tr><tr><td>File đã có</td><td><code>AgencyController</code> (<code>DELETE /api/v1/agencies/{agencyId}</code>, <code>POST /api/v1/agencies/{agencyId}/restore</code>), <code>WorkspaceRepository.findByAgencyId</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/v1/agencies/{agencyId}</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;Void&gt; (data = null)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/agencies/{agencyId}/restore</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;AgencyResponse&gt;</span></span></code></pre></div><p>Luồng xóa chỉ đổi <code>status</code>/<code>deletedAt</code> (soft delete) — không xóa cứng. Job xóa cứng sau 30 ngày thuộc thiết kế kỹ thuật riêng, ngoài phạm vi FR.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Cập nhật <code>agencies</code>: <code>status = SOFT_DELETED</code>, <code>deletedAt = now</code>.</li><li>Cập nhật <code>workspaces</code> (cascade): mọi Workspace có <code>agency_id = agencyId</code> → <code>status = SOFT_DELETED</code>, <code>deletedAt = now</code>.</li><li>Restore: <code>agencies</code> → <code>ACTIVE</code>/<code>deletedAt = null</code>; các Workspace con → <code>ACTIVE</code>/<code>deletedAt = null</code>/<code>updatedAt = now</code>.</li><li>Không migration (Workspace đã có FK <code>agency_id</code> + <code>status</code>/<code>deleted_at</code>).</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><h3 id="removeagency" tabindex="-1">removeAgency <a class="header-anchor" href="#removeagency" aria-label="Permalink to &quot;removeAgency&quot;">​</a></h3><ol><li><code>findAgencyOrThrow(agencyId)</code> → 404 nếu không có.</li><li>Check <code>ownerId == currentUser.id</code> → nếu không, <code>NOT_AGENCY_OWNER</code> (403).</li><li>Set Agency <code>status = SOFT_DELETED</code>, <code>deletedAt = now</code>, save.</li><li><code>workspaceRepository.findByAgencyId(agencyId)</code> → mỗi Workspace set <code>SOFT_DELETED</code> + <code>deletedAt = now</code>, save (cascade).</li></ol><h3 id="restoreagency" tabindex="-1">restoreAgency <a class="header-anchor" href="#restoreagency" aria-label="Permalink to &quot;restoreAgency&quot;">​</a></h3><ol><li><code>findAgencyOrThrow</code> → 404; owner-check → 403.</li><li><code>status != SOFT_DELETED</code> → <code>AGENCY_NOT_DELETED</code> (400).</li><li><code>deletedAt == null</code> hoặc quá <code>RESTORE_WINDOW_DAYS</code> (30) → <code>RESTORE_WINDOW_EXPIRED</code> (410).</li><li>Set Agency <code>ACTIVE</code>, <code>deletedAt = null</code>, <code>updatedAt = now</code>.</li><li><code>workspaceRepository.findByAgencyId(agencyId)</code> → mỗi Workspace con set <code>ACTIVE</code>, <code>deletedAt = null</code>, <code>updatedAt = now</code> (cascade).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>Agency</code> + <code>Workspace</code> entity/repository (đã có)</td></tr><tr><td>Bị chặn</td><td>Job xóa cứng định kỳ (thiết kế riêng)</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Cascade restore quá rộng:</strong> <code>restoreAgency</code> set mọi Workspace con về <code>ACTIVE</code>, kể cả Workspace đã bị soft-delete độc lập trước đó (FR 3.4.15) → hồi sinh ngoài ý muốn. Cần cờ phân biệt (ví dụ <code>deleted_with_agency</code>) nếu BA muốn chính xác — xem spec.md mục &quot;Cần xác nhận&quot;.</li><li><strong>Job xóa cứng sau 30 ngày:</strong> chưa có scheduler, ngoài phạm vi FR.</li></ul>`,18)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
